'use strict';

// Sarvam-backed STT/TTS client. Replaces the browser SpeechRecognition /
// speechSynthesis implementation entirely — audio never leaves the device
// unencrypted-and-unproxied; both legs go through the Catalyst function so
// the Sarvam key stays server-side.

const ASSISTANT_FUNCTION_URL = process.env.REACT_APP_VOICE_ASSISTANT_URL;

function buildUrl(path) {
  const base = (ASSISTANT_FUNCTION_URL || '').replace(/\/+$/, '');
  return `${base}${path}`;
}

export const VOICE_PROFILE = {
  languageCode: 'en-IN', // Sarvam doesn't currently expose en-AU — same open question as TTS.
};

// --- Speech-to-text --------------------------------------------------------

function blobToBase64(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result.split(',')[1]);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

export async function transcribeAudio(blob, { languageCode = VOICE_PROFILE.languageCode } = {}) {
  if (!ASSISTANT_FUNCTION_URL) throw new Error('Assistant function URL is not configured.');

  const audioBase64 = await blobToBase64(blob);

  const response = await fetch(buildUrl('/stt'), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ audioBase64, mimeType: blob.type, languageCode }),
  });

  if (!response.ok) {
    const bodyText = await response.text().catch(() => '');
    console.error('[STT] Function returned non-OK status:', response.status, bodyText);
    throw new Error(`STT function error: ${response.status}`);
  }

  const data = await response.json();
  return data.transcript || '';
}

// --- Text-to-speech ----------------------------------------------------

let currentAudio = null;

export async function speak(text, { languageCode = VOICE_PROFILE.languageCode, onStart, onEnd, onError } = {}) {
  if (!text || !ASSISTANT_FUNCTION_URL) {
    onError?.('unsupported');
    return null;
  }

  cancelSpeech();

  try {
    const response = await fetch(buildUrl('/tts'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text, languageCode }),
    });

    if (!response.ok || !response.body) {
      throw new Error(`TTS function error: ${response.status}`);
    }

    const arrayBuffer = await response.arrayBuffer();
    const blob = new Blob([arrayBuffer], { type: 'audio/mpeg' });
    const url = URL.createObjectURL(blob);
    const audio = new Audio(url);

    currentAudio = audio;
    onStart?.();

    audio.onended = () => {
      URL.revokeObjectURL(url);
      if (currentAudio === audio) currentAudio = null;
      onEnd?.();
    };

    audio.onerror = () => {
      URL.revokeObjectURL(url);
      if (currentAudio === audio) currentAudio = null;
      onError?.('playback_error');
    };

    await audio.play();
    return audio;
  } catch (err) {
    console.error('[TTS] speak error:', err.message || err);
    onError?.(err.message || 'tts_error');
    return null;
  }
}

export function cancelSpeech() {
  if (currentAudio) {
    currentAudio.pause();
    currentAudio = null;
  }
}

// Kept for API compatibility with the old browser-voice implementation —
// there's no client-side voice list to warm up with Sarvam, so this is a
// no-op unless/until we want to pre-request mic permission here instead.
export function primeVoices() {}

export default { transcribeAudio, speak, cancelSpeech, primeVoices, VOICE_PROFILE };
